read_inetrc() ->
    File = case application:get_env(inetrc) of
               {ok, Value} when is_list(Value) -> Value;
               {ok, Value} when is_atom(Value) -> atom_to_list(Value);
               undefined -> os:getenv("ERL_INETRC")
           end,
    case is_list(File) of
        true -> try_get_rc(File);
        false -> {nofile,[]}
    end.

try_get_rc(File) ->
    case get_rc(File) of
	error -> {nofile,[]};
	Ls ->    {File,Ls}
    end.    

get_rc(File) ->
    case get_file(File) of
	{ok,Bin} ->
	    case parse_inetrc(Bin) of
		{ok,Ls} -> 
		    Ls;
		_Error -> 
		    error("parse error in ~ts~n", [File]),
